mapper.select:
select h.bp_id, h.customer_number as cst_no,--总行客户号 h.bp_name as cst_nm_s,--客户名称 nvl((select v.ATTRIBUTE1 from sys_code_value_b_v v where v.CODE='BP.REGISTRATION_NUM_TYPE' and v.code_value=h.registration_num_type),'null')as inst_ident_tp,--机构证件类型 nvl(h.register_cert_num,'null') as ident_no,--证件号码 nvl(case when h.registration_num_type='07' then h.register_cert_num else null end,'null') unifd_socl_crdt_cd,--统一社会信用代码 nvl((select v.ATTRIBUTE1 from sys_code_value_b_v v where v.CODE='HLS.CUSTOMER_TYPE' and v.code_value=h.head_office_bp_type),'null')as cst_tp,--客户类型 nvl((select fc.digital_code from hls_bp_master_address hd,fnd_country fc where hd.bp_id=h.bp_id and hd.address_type='REGISTERED_ADDRESS' and fc.country=hd.country),'null')rgstrtn_cty_and_dstc_cd,--国家和地区代码 nvl((select fc.digital_code from fnd_country fc where fc.country=h.business_area),'null')maincorprtnactvctyordstccd,--主要经营活动所在国家/地区
nvl(h.enterprise_affiliation,'null') as entp_atch_rltnp,--企业隶属关系 nvl((select v.ATTRIBUTE1 from sys_code_value_b_v v where v.CODE='ZX_ECONOMICTYPE' and v.code_value=h.bp_financial_type),'null')as ecnm_tp,--经济类型 nvl(h.legal_person,'null') as lgl_rprs_nm,--法定代表人/经营者名称 nvl(h.business_scope,'null') as corprtn_scop1,--经营范围 case when nvl(h.credit_customer,'N')='Y' then '1' else '0' end crdt_cst_flg,--信用客户标志 h.is_first_success from hls_bp_master h where 1=1
and h.customer_number = #{cstNo}
